 1	use std::path::{Path, PathBuf};
 2	use std::time::SystemTime;
 3	
 4	/// One file the index knows about.
 5	pub struct Entry {
 6	    pub path: PathBuf,
 7	    pub modified: SystemTime,
 8	    pub headings: Vec<String>,
 9	}
10	
11	/// Walks `root` and returns every Markdown file, newest first.
12	pub fn index(root: &Path) -> Vec<Entry> {
13	    let mut out: Vec<Entry> = walk(root)
14	        .filter(|p| p.extension() == Some("md".as_ref()))
15	        .filter_map(|p| entry(&p).ok())
16	        .collect();
17	    out.sort_by(|a, b| b.modified.cmp(&a.modified));
18	    out
19	}
20	
21	fn entry(path: &Path) -> std::io::Result<Entry> {
22	    let meta = std::fs::metadata(path)?;
23	    let text = std::fs::read_to_string(path)?;
24	    Ok(Entry {
25	        path: path.to_path_buf(),
26	        modified: meta.modified()?,
27	        headings: text
28	            .lines()
29	            .filter(|l| l.starts_with('#'))
30	            .map(|l| l.trim_start_matches('#').trim().to_string())
31	            .collect(),
32	    })
33	}
34	
35	fn walk(root: &Path) -> impl Iterator<Item = PathBuf> {
36	    // TODO: honour .gitignore; today this walks node_modules too.
37	    walkdir::WalkDir::new(root)
38	        .into_iter()
39	        .filter_map(Result::ok)
40	        .map(|e| e.into_path())
41	}

