fn entry(path: &Path, prev: Option<&Entry>) -> std::io::Result<Entry> {
    let meta = std::fs::metadata(path)?;
    if let Some(prev) = prev.filter(|p| p.matches(&meta)) {
        return Ok(prev.clone());
    }
